/**
 * Course file model.
 *
 * A course is plain JSON so it can be hand-authored, generated by a mapping
 * script, or produced by the in-app "walk and mark" recorder — see
 * `courses/README.md` for the authoring guide.
 */

import type { LatLng } from './geo.js';

export type HazardKind = 'water' | 'bunker' | 'ood' | 'layup' | 'other';

export interface Hazard {
  name: string;
  kind: HazardKind;
  /** Near edge — the point you must carry. */
  carry: LatLng;
  /** Far edge, when the hazard is wide enough that clearing it matters. */
  far?: LatLng;
}

export interface Tee {
  /** e.g. "Blue", "White", "Forward". */
  name: string;
  position: LatLng;
  /** Scorecard length in metres, when known. Informational only. */
  lengthMeters?: number;
}

export interface Green {
  front: LatLng;
  center: LatLng;
  back: LatLng;
}

export interface Hole {
  number: number;
  par: number;
  /** Stroke index / handicap ranking, 1 = hardest. */
  handicap?: number;
  tees: Tee[];
  green: Green;
  hazards?: Hazard[];
  /** Optional dogleg aiming point; used for layup yardages. */
  aim?: LatLng;
}

export interface Course {
  id: string;
  name: string;
  /** Free-form, e.g. "Nowhere, CA". */
  location?: string;
  /** Schema version so old saved courses can be migrated rather than dropped. */
  version: 1;
  holes: Hole[];
}

export interface ValidationIssue {
  path: string;
  message: string;
}

const isFiniteNumber = (v: unknown): v is number =>
  typeof v === 'number' && Number.isFinite(v);

function validateLatLng(value: unknown, path: string, issues: ValidationIssue[]): void {
  if (typeof value !== 'object' || value === null) {
    issues.push({ path, message: 'expected an object with lat and lng' });
    return;
  }
  const point = value as Partial<LatLng>;
  if (!isFiniteNumber(point.lat) || point.lat < -90 || point.lat > 90) {
    issues.push({ path: `${path}.lat`, message: 'lat must be a number between -90 and 90' });
  }
  if (!isFiniteNumber(point.lng) || point.lng < -180 || point.lng > 180) {
    issues.push({ path: `${path}.lng`, message: 'lng must be a number between -180 and 180' });
  }
  if (point.elevation !== undefined && !isFiniteNumber(point.elevation)) {
    issues.push({ path: `${path}.elevation`, message: 'elevation must be a number (metres)' });
  }
}

/**
 * Structural validation of a parsed course file.
 *
 * Deliberately strict about coordinates: a typo in a longitude sign puts the
 * green on the wrong continent, and a rangefinder that confidently reports
 * 8,000 yards is worse than one that refuses to load.
 */
export function validateCourse(input: unknown): ValidationIssue[] {
  const issues: ValidationIssue[] = [];

  if (typeof input !== 'object' || input === null) {
    return [{ path: '$', message: 'course must be a JSON object' }];
  }
  const course = input as Partial<Course>;

  if (typeof course.id !== 'string' || course.id.trim() === '') {
    issues.push({ path: '$.id', message: 'id is required' });
  }
  if (typeof course.name !== 'string' || course.name.trim() === '') {
    issues.push({ path: '$.name', message: 'name is required' });
  }
  if (course.version !== 1) {
    issues.push({ path: '$.version', message: 'version must be 1' });
  }
  if (!Array.isArray(course.holes) || course.holes.length === 0) {
    issues.push({ path: '$.holes', message: 'at least one hole is required' });
    return issues;
  }

  const seenNumbers = new Set<number>();
  course.holes.forEach((raw, index) => {
    const path = `$.holes[${index}]`;
    if (typeof raw !== 'object' || raw === null) {
      issues.push({ path, message: 'hole must be an object' });
      return;
    }
    const hole = raw as Partial<Hole>;

    if (!isFiniteNumber(hole.number) || hole.number < 1) {
      issues.push({ path: `${path}.number`, message: 'number must be a positive integer' });
    } else if (seenNumbers.has(hole.number)) {
      issues.push({ path: `${path}.number`, message: `duplicate hole number ${hole.number}` });
    } else {
      seenNumbers.add(hole.number);
    }

    if (!isFiniteNumber(hole.par) || hole.par < 3 || hole.par > 6) {
      issues.push({ path: `${path}.par`, message: 'par must be between 3 and 6' });
    }

    if (!Array.isArray(hole.tees) || hole.tees.length === 0) {
      issues.push({ path: `${path}.tees`, message: 'at least one tee is required' });
    } else {
      hole.tees.forEach((tee, teeIndex) => {
        const teePath = `${path}.tees[${teeIndex}]`;
        if (typeof tee?.name !== 'string' || tee.name.trim() === '') {
          issues.push({ path: `${teePath}.name`, message: 'tee name is required' });
        }
        validateLatLng(tee?.position, `${teePath}.position`, issues);
      });
    }

    if (typeof hole.green !== 'object' || hole.green === null) {
      issues.push({ path: `${path}.green`, message: 'green with front/center/back is required' });
    } else {
      validateLatLng(hole.green.front, `${path}.green.front`, issues);
      validateLatLng(hole.green.center, `${path}.green.center`, issues);
      validateLatLng(hole.green.back, `${path}.green.back`, issues);
    }

    hole.hazards?.forEach((hazard, hazardIndex) => {
      const hazardPath = `${path}.hazards[${hazardIndex}]`;
      if (typeof hazard?.name !== 'string' || hazard.name.trim() === '') {
        issues.push({ path: `${hazardPath}.name`, message: 'hazard name is required' });
      }
      validateLatLng(hazard?.carry, `${hazardPath}.carry`, issues);
      if (hazard?.far !== undefined) {
        validateLatLng(hazard.far, `${hazardPath}.far`, issues);
      }
    });

    if (hole.aim !== undefined) validateLatLng(hole.aim, `${path}.aim`, issues);
  });

  return issues;
}

export class CourseValidationError extends Error {
  constructor(readonly issues: ValidationIssue[]) {
    super(
      `Invalid course file:\n${issues
        .map((issue) => `  ${issue.path}: ${issue.message}`)
        .join('\n')}`,
    );
    this.name = 'CourseValidationError';
  }
}

/** Parse + validate in one step, throwing a readable error on bad input. */
export function parseCourse(input: unknown): Course {
  const issues = validateCourse(input);
  if (issues.length > 0) throw new CourseValidationError(issues);
  const course = input as Course;
  return {
    ...course,
    holes: [...course.holes].sort((a, b) => a.number - b.number),
  };
}

export function findHole(course: Course, holeNumber: number): Hole | undefined {
  return course.holes.find((hole) => hole.number === holeNumber);
}

/** Tee matching by name, falling back to the first tee on the hole. */
export function selectTee(hole: Hole, teeName?: string): Tee | undefined {
  if (teeName) {
    const match = hole.tees.find(
      (tee) => tee.name.toLowerCase() === teeName.toLowerCase(),
    );
    if (match) return match;
  }
  return hole.tees[0];
}

/** Tee names offered by every hole, in first-seen order. */
export function availableTeeNames(course: Course): string[] {
  const names: string[] = [];
  for (const hole of course.holes) {
    for (const tee of hole.tees) {
      if (!names.includes(tee.name)) names.push(tee.name);
    }
  }
  return names.filter((name) =>
    course.holes.every((hole) => hole.tees.some((tee) => tee.name === name)),
  );
}

export function coursePar(course: Course): number {
  return course.holes.reduce((total, hole) => total + hole.par, 0);
}
